import React from 'react';
// Use the child prop if it exists, or inherit from the parent prop
export const mergeStyleProp = (parentValue, childValue) => childValue !== undefined ? childValue : parentValue;
export const findChildByType = (children, type) => React.Children.map(children, (child) => {
    if (child?.type) {
        const name = child.type.displayName;
        if (name && type.includes(name)) {
            return child;
        }
    }
}) || [];
