import React, { useEffect } from 'react';
import { BrowserRouter as Router, Navigate, Outlet, Route, Routes, useLocation } from 'react-router';
import { LandingPage } from '../pages';
import { DrawerLayout } from '@brightlayer-ui/react-components';
import { ContactFab, SharedToolbar } from '../components';
import { NavigationDrawer } from './navigationDrawer';
import { RootState, useAppSelector } from '../redux';
import { Menu } from '@mui/icons-material';
import { pageDefinitions, SimpleNavItem } from '../../__configuration__/navigationMenu/navigation';
import { getScheduledSiteConfig } from '../../__configuration__/themes';
import AppBar from '@mui/material/AppBar';
import Box from '@mui/material/Box';
import Toolbar from '@mui/material/Toolbar';
import Typography from '@mui/material/Typography';
import * as Colors from '@brightlayer-ui/colors';
import { AnnouncementAppbar } from '../components/announcements/announcementAppbar';
import { SystemStyleObject } from '@mui/system';

const buildRoutes = (routes: SimpleNavItem[], url: string): React.JSX.Element[] => {
    let ret: any[] = [];
    for (const route of routes) {
        if (route.component) {
            ret.push(
                <Route
                    path={`${url === '' ? '' : `${url}/`}${route.url ?? ''}`}
                    key={`${url}/${route.url ?? ''}`}
                    element={route.component}
                />
            );
        }
        if (route.pages) {
            ret = ret.concat(buildRoutes(route.pages || [], `${url === '' ? '' : `${url}/`}${route.url ?? ''}`));
        }
    }
    return ret;
};

const ScrollToTop = (): React.JSX.Element | null => {
    const { pathname, hash } = useLocation();

    useEffect(() => {
        // if an anchor link is present, scroll to the anchor link;
        // else scroll the page to the top

        if (hash) {
            const id = hash.replace('#', '');
            const headline = document.getElementById(id);
            if (headline) {
                window.scrollTo(0, headline.offsetTop);
            } else {
                window.scrollTo(0, 0);
            }
        } else {
            window.scrollTo(0, 0);
        }
    }, [pathname, hash]);

    return null;
};

// Type-safe wrapper for Router to handle React 19 compatibility
const RouterWrapper: React.FC<{ children: React.ReactNode }> = ({ children }) => {
    const RouterComponent = Router as any;
    return <RouterComponent basename={process.env.PUBLIC_URL || '/'}>{children}</RouterComponent>;
};

export const MainRouter = (): React.JSX.Element => {
    const title = useAppSelector((state: RootState) => state.app.pageTitle);
    const selectedTheme = useAppSelector((state: RootState) => state.app.theme);
    const className = getScheduledSiteConfig(selectedTheme).className;
    const sidebarOpen = useAppSelector((state: RootState) => state.app.sidebarOpen);
    const showBanner = useAppSelector((state: RootState) => state.app.showBanner);
    return (
        <RouterWrapper>
            <ScrollToTop />
            <AnnouncementAppbar />
            <DrawerLayout
                drawer={<NavigationDrawer />}
                className={className}
                sx={(theme): SystemStyleObject => ({
                    display: 'block',
                    '& .BluiDrawerLayout-drawer': {
                        height: showBanner
                            ? { xs: `calc(100% - ${theme.spacing(7)}px)`, sm: `calc(100% - ${theme.spacing(8)}px)` }
                            : undefined,
                        zIndex: 'modal',
                    },
                })}
            >
                <Routes>
                    <Route path="/" element={<LandingPage />} />

                    <Route
                        path="*"
                        element={
                            <>
                                <SharedToolbar title={title} navigationIcon={<Menu />} />
                                <Box sx={{ minHeight: { xs: `calc(50vh - ${104}px)`, sm: `calc(50vh - ${112}px)` } }}>
                                    <Outlet />
                                </Box>
                                {/* Footer Section */}
                                <AppBar
                                    position={'static'}
                                    sx={(theme): SystemStyleObject => ({
                                        zIndex: 0,
                                        backgroundColor: Colors.black[900],
                                        color: Colors.black[50],
                                        textAlign: 'center',
                                        mt: '50vh',
                                        transform: 'inherit',
                                        transition: theme.transitions.create('width'),
                                    })}
                                    elevation={0}
                                    style={{ width: `calc(100% - ${sidebarOpen ? 350 : 0}px)` }}
                                >
                                    <Toolbar variant={'dense'}>
                                        <Typography variant={'caption'} align={'center'} style={{ flex: '1 1 0px' }}>
                                            {`Copyright ${new Date().getFullYear()} Eaton. Licensed under BSD-3-Clause.`}
                                        </Typography>
                                    </Toolbar>
                                </AppBar>
                            </>
                        }
                    >
                        {buildRoutes(pageDefinitions, '')}

                        {/* Catch-All Redirect to Landing Page */}
                        <Route path="*" element={<Navigate replace to={'/'} />} />
                    </Route>
                </Routes>
                <ContactFab />
            </DrawerLayout>
        </RouterWrapper>
    );
};
